WITH valid AS (SELECT *, CASE WHEN country IN ('TH', 'JP') THEN 'Group A' ELSE 'Other' END AS country_group, COALESCE(city, 'OTHER') AS resolved_city FROM suppliers WHERE city IS DISTINCT FROM 'New York' AND rating < 2.7) SELECT CASE WHEN rating >= 4.0 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_tier, SUM(CASE WHEN city = 'Bangkok' THEN rating ELSE 0 END) AS bangkok_rating, COUNT(*) AS row_count FROM valid GROUP BY CASE WHEN rating >= 4.0 THEN 'PREMIUM' ELSE 'STANDARD' END
